def load():
    import os,re
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

def transform(g):
    import copy
    h,w=len(g),len(g[0])
    out=[r[:] for r in g]
    fives=[(r,c) for r in range(h) for c in range(w) if g[r][c]==5]
    # pattern 5: adjacent to non-zero
    def has_nb(p): 
        r,c=p
        return any(0<=r+dr<h and 0<=c+dc<w and g[r+dr][c+dc]!=0 and (dr,dc)!=(0,0) for dr in(-1,0,1) for dc in(-1,0,1))
    anchors=[p for p in fives if has_nb(p)]
    others=[p for p in fives if p not in anchors]
    a=anchors[0]
    for (r0,c0) in others:
        dy,dx=r0-a[0],c0-a[1]
        for r in range(h):
            for c in range(w):
                if g[r][c]!=0 and g[r][c]!=5:
                    nr,nc=r+dy,c+dx
                    if 0<=nr<h and 0<=nc<w: out[nr][nc]=g[r][c]
    return out

